"""Dedicated teacher/remedial/worksheet workflow using synthetic Firebase data."""
import json
from playwright.sync_api import sync_playwright
D={'schemaVersion':1,'revision':1,'streams':{},'classes':{cl:{'label':'Class '+cl,'sections':{'a':{'name':'A','stream':'','subjects':{'english':{'name':'English','code':''}},'students':{'one':{'name':'Synthetic Student '+cl,'roll':'001','subjects':{'english':True}}}}}} for cl in ['X','XII']}}
F={'schemaVersion':1,'revision':1,'classes':{'X':{'classId':'X','teachers':{'one':{'name':'Synthetic Teacher','designation':'TGT','subjects':'English','teachingSections':'A','status':'active'}},'roles':{'a':{'classTeacher':'one','coClassTeacher':''}}},'XII':{'classId':'XII','teachers':{},'roles':{}}}}
APP='export function initializeApp(c){return {options:c}}export function getApps(){return [];}'
AUTH="export function getAuth(){return {}}export const browserLocalPersistence={};export async function setPersistence(){}export function onAuthStateChanged(a,cb){cb(window.__guest?null:{uid:'principal-test',getIdToken:async()=> 'test-token'});}export async function signOut(){}"
DB='''const draft=DRAFT,faculty=FACULTY;let mission=null;const callbacks={};window.__teacherReads=[];export function getDatabase(){return {}}export function ref(d,p){return p;}export async function get(p){window.__teacherReads.push(p);return {val:()=> 'principal-test'};}export function onValue(p,cb){window.__teacherReads.push(p);(callbacks[p]||=[]).push(cb);cb({val:()=>p==='cbse/draft'?draft:p==='cbse/facultyDraft'?faculty:mission});return ()=>{};}export async function runTransaction(p,fn){const next=fn(structuredClone(mission));if(next===undefined)return {committed:false};mission=structuredClone(next);window.__teacherMission=structuredClone(next);for(const cb of callbacks[p]||[])cb({val:()=>structuredClone(mission)});return {committed:true,snapshot:{val:()=>structuredClone(mission)}};}'''.replace('DRAFT',json.dumps(D)).replace('FACULTY',json.dumps(F))
def sdk(route):
 url=route.request.url;route.fulfill(content_type='application/javascript',body=APP if url.endswith('firebase-app.js') else AUTH if url.endswith('firebase-auth.js') else DB)
with sync_playwright() as p:
 browser=p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
 page=browser.new_page();page.route('https://www.gstatic.com/firebasejs/**',sdk);page.goto('http://127.0.0.1:8000/cbse-mission.html');page.locator('#mission-tools').wait_for(state='visible')
 page.locator('#mission-basic-file').set_input_files({'name':'Class_X_All_Basic.csv','mimeType':'text/csv','buffer':b'Class,Section,StudentName,Gender,FatherName,FatherMobile,CurrentAddress\nX,A,Synthetic Student X,Female,Synthetic Parent,1234567890,Synthetic address'})
 page.get_by_role('heading',name='Review student basic-data import',exact=True).wait_for();assert '1 of 1 rows matched' in page.locator('#mission-fields').inner_text();assert page.evaluate('window.__teacherMission') is None
 page.locator('#mission-save').click();page.locator('#mission-editor').wait_for(state='hidden');assert page.evaluate("window.__teacherMission.students['X:a:one'].gender")=='girl'
 print('PASS reviewed basic CSV import saves gender and private contacts only after Save')
 page.get_by_role('button',name='Teacher monitoring',exact=True).click();page.get_by_role('button',name='Teacher profile: Synthetic Teacher',exact=True).click();page.get_by_role('heading',name='Synthetic Teacher',exact=True).wait_for()
 page.get_by_role('button',name='Remedial session',exact=True).click();assert page.locator('[name=kind]').input_value()=='remedial';assert page.locator('[name=staffId]').input_value()=='X:one'
 page.locator('[name=sectionKey]').select_option('X:a');page.locator('[name=notes]').fill('Targeted reading support');page.locator('[name=detail_status]').select_option('conducted');page.locator('[name=detail_start]').fill('10:30');page.locator('[name=detail_end]').fill('11:00');page.locator('[name=detail_planned]').fill('20');page.locator('[name=detail_attended]').fill('21');page.locator('#mission-save').click();page.locator('#mission-editor-error').wait_for(state='visible');assert 'cannot exceed' in page.locator('#mission-editor-error').inner_text();page.locator('[name=detail_attended]').fill('18');page.locator('#mission-save').click();page.locator('#mission-editor').wait_for(state='hidden');assert 'Students attended: 18' in page.locator('#mission-view').inner_text()
 page.evaluate("location.hash='tab=remedial'");page.get_by_role('heading',name='Remedial classes',exact=True).wait_for();page.get_by_role('heading',name='Remedial session register',exact=True).wait_for();assert 'Targeted reading support' in page.locator('#mission-view').inner_text()
 page.get_by_role('combobox',name='Monitoring class',exact=True).select_option('XII');assert 'Targeted reading support' not in page.locator('#mission-view').inner_text();page.get_by_role('combobox',name='Monitoring class',exact=True).select_option('X');assert 'Targeted reading support' in page.locator('#mission-view').inner_text()
 for width in [360,768,1440]:
  page.set_viewport_size({'width':width,'height':900});assert page.evaluate('document.documentElement.scrollWidth<=innerWidth')
 page.evaluate("location.hash='tab=worksheets'");page.get_by_role('button',name='Add worksheet / practice record').click();page.locator('[name=staffId]').select_option('X:one');page.locator('[name=sectionKey]').select_option('X:a');page.locator('[name=notes]').fill('Answer-writing worksheet');page.locator('[name=detail_status]').select_option('checked');page.locator('[name=detail_planned]').fill('25');page.locator('[name=detail_submitted]').fill('20');page.locator('[name=detail_checked]').fill('18');page.locator('#mission-save').click();page.locator('#mission-editor').wait_for(state='hidden');assert 'Students checked / reviewed: 18' in page.locator('#mission-view').inner_text()
 page.evaluate("location.hash='tab=ct'");page.get_by_role('heading',name='Section CT / Co-CT watch',exact=True).wait_for();assert page.get_by_role('button',name='Synthetic Teacher',exact=True).is_visible()
 print('PASS teacher directory/profile, structured remedial entry, invalid attendance, filters, worksheet completion, CT watch and responsive layout')
 guest=browser.new_page();guest.add_init_script('window.__guest=true');guest.route('https://www.gstatic.com/firebasejs/**',sdk);guest.goto('http://127.0.0.1:8000/cbse-mission.html#tab=remedial');guest.get_by_role('heading',name='Remedial classes',exact=True).wait_for();assert guest.get_by_role('button',name='Add remedial session').count()==0;assert guest.evaluate('window.__teacherReads')==['cbse/public']
 print('PASS public monitoring overview exposes no private teacher records or feeding controls')
 browser.close()
